import{_ as a,c as l,o as t,ak as c}from"./chunks/framework.CtX3_w5e.js";const y=JSON.parse('{"title":"mycat","description":"","frontmatter":{"title":"mycat","hugoSource":"computer-science/database/mycat.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/database/2026-11-17-mycat.md","filePath":"computer-science/database/2026-11-17-mycat.md","lastUpdated":1794887319000}'),i={name:"computer-science/database/2026-11-17-mycat.md"};function r(o,e,d,s,n,m){return t(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="mycat" tabindex="-1">mycat <a class="header-anchor" href="#mycat" aria-label="Permalink to “mycat”">​</a></h1><ul><li><a href="https://segmentfault.com/a/1190000021987297" target="_blank" rel="noreferrer">那些年非常火的MyCAT是什么？</a></li><li><a href="https://blog.csdn.net/m0_74436895/article/details/142969704" target="_blank" rel="noreferrer">MyCat(看这一篇就够了）</a><ul><li>应用场景 <ul><li>MySQL读写分离</li><li>分库分表</li><li>数据库路由器</li><li>整合数据源 <ul><li>当一个项目需要用到多种数据源如Oracle, MySQL, SQL Server, <code>PostgreSQL</code>时，可以利用<code>Mycat</code>进行整合，只需访问<code>Mycat</code>这一个数据源就行</li></ul></li></ul></li><li>逻辑库 schema <ul><li>业务开发人员通常在实际应用中并不需要知道中间件的存在，只需要关注数据库，所以数据库中间件可以被当做一个或多个数据库集群构成的逻辑库</li></ul></li><li>逻辑表 table <ul><li>既然有逻辑库，就会有逻辑表。在分布式数据库中，对于应用来说，读写数据的表就是逻辑表。逻辑表可以分布在一个或多个分片库中，也可以不分片</li></ul></li><li>Mycat的原理最重要的一个动词是拦截，它拦截用户发送过来的SQL语句</li></ul></li></ul><h2 id="mycat-如何实现高可用" tabindex="-1"><code>Mycat</code> 如何实现高可用 <a class="header-anchor" href="#mycat-如何实现高可用" aria-label="Permalink to “Mycat 如何实现高可用”">​</a></h2><ul><li>基于<code>keepalived</code>的<code>MyCat</code>高可用技术 <ul><li><code>Keepalived</code>通过<code>VRRP</code>协议实现虚拟IP(VIP)的自动漂移，当主节点故障时，VIP会自动切换到备用节点，实现MyCat服务的高可用</li></ul></li><li>HAProxy+Keepalived实现高可用与负载均衡 <ul><li>HAProxy实现MyCat多节点的负载均衡</li><li>Keepalived实现HAProxy自身的高可用</li><li>同时解决了MyCat的负载均衡器的高可用问题</li></ul></li></ul>',4)])])}const _=a(i,[["render",r]]);export{y as __pageData,_ as default};
